css:
.sdk-probe{font:13px/1.5 system-ui,sans-serif;color:#222;display:grid;gap:10px;padding:12px;max-width:100%;box-sizing:border-box}
.sdk-probe h3{margin:0;font-size:16px;font-weight:650}
.sdk-probe .hint{margin:0;color:#666;overflow-wrap:anywhere}
.sdk-probe label{font-weight:600}
.sdk-probe input{box-sizing:border-box;width:100%;min-width:0;border:1px solid #adb5bd;border-radius:6px;padding:8px;background:#fff;color:#171717}
.sdk-probe .actions{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}
.sdk-probe button{padding:8px 5px;min-width:0;background:#f7f7f7;color:#222;border:1px solid #b5b5b5;border-radius:7px;cursor:pointer}
.sdk-probe button:hover{background:#e9e9e9}
.sdk-probe button:focus-visible,.sdk-probe input:focus-visible{outline:2px solid #346feb;outline-offset:2px}
#probe-state{margin:0;font-weight:600}
#probe-result{margin:0;white-space:pre-wrap;overflow-wrap:anywhere;max-height:240px;overflow:auto;padding:8px;border:1px solid #ddd;border-radius:7px;background:#fafafa}
@media(max-width:250px){.sdk-probe .actions{grid-template-columns:1fr}}

js:
(()=>{
  'use strict';
  const browser=OpenDeskSDK.browser;
  const root=OpenDeskTool.root;
  const urlInput=root.querySelector('#probe-url');
  const stateText=root.querySelector('#probe-state');
  const resultText=root.querySelector('#probe-result');
  const session={tabRef:null,watch:null};
  const currentUrl=()=>{
    const url=new URL(urlInput.value.trim());
    if(!['http:','https:'].includes(url.protocol)||url.username||url.password)
      throw Object.assign(new Error('仅允许无凭据 HTTP(S) 地址'),{code:'E_SCHEMA'});
    return url.href;
  };
  const requireRef=(value,label)=>{
    if(typeof value!=='string')throw Object.assign(new Error('请先'+label),{code:'E_CONTEXT'});
    return value;
  };
  const currentWatch=()=>{
    if(!session.watch)throw Object.assign(new Error('请先开始网络观察'),{code:'E_CONTEXT'});
    return session.watch;
  };
  const operations={
    open:async()=>{const result=await browser.tabs.create({url:currentUrl()});session.tabRef=result.tabRef;return result},
    focus:()=>browser.tabs.activateOwned({tabRef:requireRef(session.tabRef,'打开测试标签页')}),
    http:()=>browser.network.request({method:'GET',url:currentUrl(),config:{responseType:'text',timeout:7000}}),
    side:()=>browser.sidePanel.openSelf(),
    shot:()=>browser.screenshot.captureVisible({tabRef:requireRef(session.tabRef,'打开标签页')}),
    observe:async()=>{
      const url=new URL(currentUrl());
      const watch=await browser.network.watch({tabRef:requireRef(session.tabRef,'打开标签页'),
        origin:url.origin,durationMs:30000,maxEvents:80,maxBufferedBytes:65536});
      session.watch=watch;
      return {id:watch.id,expiresAt:watch.expiresAt};
    },
    events:()=>currentWatch().read({limit:25}),
    status:()=>currentWatch().status(),
    stop:()=>currentWatch().stop(),
    cancel:()=>currentWatch().cancel(),
    export:()=>currentWatch().export(),
    close:async()=>{
      const result=await currentWatch().close();
      session.watch=null;return result;
    }
  };
  root.addEventListener('click',event=>{
    const key=event.target?.closest?.('button[data-op]')?.dataset.op;
    if(!key||!Object.hasOwn(operations,key))return;
    stateText.textContent='正在执行：'+key+'（如出现确认栏，请主动点击）';
    Promise.resolve().then(()=>operations[key]()).then(result=>{
      stateText.textContent='已返回：'+key;
      resultText.textContent=JSON.stringify(result,null,2).slice(0,5000);
    },error=>{
      stateText.textContent='拒绝或失败：'+key;
      resultText.textContent=(error?.code||'E_TOOL')+'：'+String(error?.message||error).slice(0,500);
    });
  });
})();
